function [M,B] = rerun_full_model_isotope_forcing( ...
    Mreference,deltaDPrecipInterval_permil)
%RERUN_FULL_MODEL_ISOTOPE_FORCING
% Re-run the isotope + biochemical chain on an existing validated
% hydraulic checkpoint using a new precipitation-isotope forcing.
%
% Hydraulics, meteorology, hydraulic fluxes, storage volumes and plant
% physiological states remain identical to Mreference.
%
% Inputs
% ------
% Mreference
%   Integrated model object generated by driver_full_model.
%
% deltaDPrecipInterval_permil
%   nTime-1 precipitation isotope values. Isotope values assigned to
%   intervals with zero actual infiltration have no physical effect.
%
% Outputs
% -------
% M
%   Recomputed full isotope/biochemical model object.
%
% B
%   Recomputed fractionation/isotope-state budget.

if nargin<2
    error('Mreference and deltaDPrecipInterval_permil are required.');
end

requiredM={ ...
    'timeDays','config','hydraulicCheckpointPath','hydraulics','grid', ...
    'meteorology'};

for k=1:numel(requiredM)
    if ~isfield(Mreference,requiredM{k})
        error('Mreference is missing required field %s.',requiredM{k});
    end
end

timeDays=Mreference.timeDays(:);
nT=numel(timeDays);
nInt=nT-1;

dP=deltaDPrecipInterval_permil(:);
if numel(dP)~=nInt || any(~isfinite(dP))
    error('deltaDPrecipInterval_permil must contain nTime-1 finite values.');
end

checkpointPath=Mreference.hydraulicCheckpointPath;
if ~isfile(checkpointPath)
    error('Hydraulic checkpoint not found: %s',checkpointPath);
end

Q=load(checkpointPath,'plantCoupled');

if ~isfield(Q,'plantCoupled')
    error('Checkpoint is missing plantCoupled.');
end

plantCoupled=Q.plantCoupled;

Crich=Mreference.hydraulics;
G=Mreference.grid;
met=Mreference.meteorology;
cfg=Mreference.config;

cfg.forcing.precipDeltaD_permil=dP;

%% ========================================================================
% 1. Resolved soil isotope transport
% ========================================================================

zoneIndex=Crich.soil.zoneIndex(:);
nZone=max(zoneIndex);

if numel(cfg.forcing.initialSoilDeltaDByZone_permil)<nZone
    error('Initial soil isotope forcing does not cover all soil zones.');
end

deltaDInitialCell_permil= ...
    cfg.forcing.initialSoilDeltaDByZone_permil(zoneIndex);

Isoil=soil_isotope_transport_richards( ...
    Crich.soil, ...
    deltaDInitialCell_permil, ...
    dP, ...
    [], ...
    cfg.soilIsotope);

%% ========================================================================
% 2. Common-root isotope boundary
% ========================================================================

Broot=prepare_root_xylem_isotope_boundary( ...
    Isoil,Crich,struct('Rstandard_DH',cfg.Rstandard_DH));

%% ========================================================================
% 3. Exact-D xylem
% ========================================================================

cfg.xylemIsotope.storageLumenInitialDeltaD= ...
    Broot.initialDeltaD_permil;
cfg.xylemIsotope.storageLivingInitialDeltaD= ...
    Broot.initialDeltaD_permil;

Xxylem=xylem_transport_dynamic_exactD( ...
    timeDays, ...
    Broot.deltaDNode_permil, ...
    Crich.hydro, ...
    plantCoupled, ...
    cfg.xylemIsotope);

%% ========================================================================
% 4. Coupled spatial leaf isotope field
% ========================================================================

Lleaf=leaf_hydraulics_dynamic_spatial_symplast( ...
    timeDays, ...
    Xxylem.leafBoundary, ...
    Crich.hydro, ...
    met, ...
    cfg.leafIsotope);

%% ========================================================================
% 5. Intracellular exact-D water
% ========================================================================

Icell=intracellular_water_dynamic_exactD( ...
    timeDays,Lleaf,cfg.intracellular);

%% ========================================================================
% 6. Biochemical/wax bridge
% ========================================================================

Bio=wax_biochemistry_from_intracellular_nominal( ...
    timeDays,Icell,cfg.biochemistry);

%% ========================================================================
% 7. Assemble run
% ========================================================================

M=struct;
M.version='2026-08-19_full_model_isotope_rerun_v1';
M.timeDays=timeDays;
M.config=cfg;

M.hydraulicCheckpointPath=checkpointPath;
M.hydraulics=Crich;
M.grid=G;
M.meteorology=met;

M.soilIsotopes=Isoil;
M.rootBoundary=Broot;
M.xylemIsotopes=Xxylem;
M.leafIsotopes=Lleaf;
M.intracellular=Icell;
M.biochemistry=Bio;

M.scope=Mreference.scope;
M.knownCurrentOmissions=Mreference.knownCurrentOmissions;

B=build_isotope_fractionation_budget(M,dP);
end
